WITH RECURSIVE ancestors AS (SELECT pay_id,cry_pay_id FROM fin.pay WHERE pay_id=#{id}
  UNION ALL SELECT p.pay_id,p.cry_pay_id FROM fin.pay p JOIN ancestors a ON a.cry_pay_id=p.pay_id)
SELECT pay_id FROM ancestors WHERE cry_pay_id IS NULL

WITH RECURSIVE descendants AS (SELECT pay_id FROM fin.pay WHERE pay_id=#{root}
  UNION ALL SELECT p.pay_id FROM fin.pay p JOIN descendants d ON p.cry_pay_id=d.pay_id)
SELECT  FROM fin.pay p JOIN descendants d USING(pay_id) ORDER BY p.pay_id
